            except (KeyError, IndexError, TypeError) as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == 'P':
            try:
                cur = cur[arg]
            except (KeyError, IndexError, TypeError) as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == '(':
            args, kwargs = arg
            args = [arg_val(target, a, scope) for a in args]
            kwargs = {k: arg_val(target, v, scope) for k, v in kwargs.items()}
            try:
                cur = cur(*args, **kwargs)
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == 'x':
            if isinstance(cur, list):
                cur = cur
            else:
                try:
                    cur = list(cur)
                except Exception as e:
                    raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == 'X':
            result = []
            def _recurse_star(obj):
                if isinstance(obj, (list, tuple)):
                    for item in obj:
                        _recurse_star(item)
                else:
                    result.append(obj)
            _recurse_star(cur)
            cur = result
        elif op in ('+', '-', '*', '#', '/', '%', ':', '&', '|', '^'):
            op_map = {
                '+': operator.add,
                '-': operator.sub,
                '*': operator.mul,
                '#': operator.floordiv,
                '/': operator.truediv,
                '%': operator.mod,
                ':': operator.pow,
                '&': operator.and_,
                '|': operator.or_,
                '^': operator.xor,
            }
            try:
                cur = op_map[op](cur, arg)
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == '~':
            try:
                cur = ~cur
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)
        elif op == '_':
            try:
                cur = -cur
            except Exception as e:
                raise PathAccessError(e, Path(_t), (i - 2) // 2)

    return cur


def _assign_op(dest, op, arg, val, path, scope):
    if op == '.':
        setattr(dest, arg, val)
    elif op == '[':
        dest[arg] = val
    elif op == 'P':
        dest[arg] = val
    else:
        raise ValueError(f'cannot assign with operation {op}')


def _format_t(path, root=T):
    if not path:
        return bbrepr(root)

    parts = [bbrepr(root)]

    for op, val in zip(path[::2], path[1::2]):
        if op == '.':
            parts.append(f'.{val}')
        elif op == '[':
            parts.append(f'[{bbrepr(val)}]')
        elif op == 'P':
            parts.append(f'[{bbrepr(val)}]')
        elif op == '(':
            args, kwargs = val
            arg_strs = [bbrepr(a) for a in args]
            kwarg_strs = [f'{k}={bbrepr(v)}' for k, v in kwargs.items()]
            all_args = ', '.join(arg_strs + kwarg_strs)
            parts.append(f'({all_args})')
        elif op == 'x':
            parts.append('.__star__()')
        elif op == 'X':
            parts.append('.__starstar__()')
        elif op in ('+', '-', '*', '#', '/', '%', ':', '&', '|', '^', '~', '_'):
            op_map = {'+': '+', '-': '-', '*': '*', '#': '//', '/': '/', '%': '%', ':': '**', '&': '&', '|': '|', '^': '^', '~': '~', '_': '-'}
            if op in ('~', '_'):
                parts[-1] = f'{op_map[op]}{parts[-1]}'
            else:
                parts.append(f' {op_map[op]} {bbrepr(val)}')

    return ''.join(parts)


def _handle_list(target, spec, scope):
    ret = []
    for item in target:
        val = scope[glom](item, spec[0], scope)
        if val is SKIP:
            continue
        if val is STOP:
            break
        ret.append(val)
    return ret


def glom(target, spec, **kwargs):
    scope = kwargs.pop('scope', _DEFAULT_SCOPE)
    if not isinstance(scope, ChainMap):
        scope = ChainMap(scope)

    default = kwargs.pop('default', _MISSING)
    skip_exc = kwargs.pop('skip_exc', _MISSING)
    glom_debug = kwargs.pop('glom_debug', GLOM_DEBUG)

    if kwargs:
        raise TypeError(f'unexpected keyword arguments: {sorted(kwargs.keys())}')

    scope = scope.new_child({
        MODE: AUTO,
        MIN_MODE: None,
        Path: Path(),
        ROOT: target,
    })

    try:
        return _glom(target, spec, scope)
    except GlomError as e:
        if not glom_debug:
            e._finalize(scope)
        if default is not _MISSING:
            return default
        raise
    except Exception as e:
        if skip_exc is not _MISSING:
            if isinstance(e, skip_exc):
                return default if default is not _MISSING else None
        raise


def register_op(op_name, **kwargs):
    _DEFAULT_SCOPE[TargetRegistry].register_op(op_name, **kwargs)


def _finalize(self, scope):
    etype, evalue, _ = sys.exc_info()
    tb_lines = traceback.format_exc().strip().splitlines()
    limit = 0
    for line in reversed(tb_lines):
        if _PKG_DIR_PATH in line:
            limit -= 1
            break
        limit += 1
    self._tb_lines = tb_lines[-limit:]
    if set(self._tb_lines[0]) <= {' ', '^', '~'}:
        self._tb_lines = self._tb_lines[1:]
    self._scope = scope


def __str__(self):
    if getattr(self, '_finalized_str', None):
        return self._finalized_str
    elif getattr(self, '_scope', None) is not None:
        self._target_spec_trace = format_target_spec_trace(self._scope, self.__wrapped)
        parts = ["error raised while processing, details below.",
                 " Target-spec trace (most recent last):",
                 self._target_spec_trace]
        parts.extend(self._tb_lines)
        self._finalized_str = "\n".join(parts)
        return self._finalized_str

    try:
        exc_get_message = self.get_message
    except AttributeError:
        exc_get_message = super().__str__
    return exc_get_message()


